{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Check GYGL/DZGL facility counts vs device counts per credit."""
import openpyxl
from collections import Counter, defaultdict

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/050%规模/01_工业锅炉/03_通用工具调用型Agent/R1/inputs"

def load(path):
    wb = openpyxl.load_workbook(BASE + "/" + path, read_only=True, data_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    H = {h: i for i, h in enumerate(rows[0])}
    return rows[1:], H

def s(v):
    return "" if v is None else str(v).strip()

d2, H2 = load("基102-2002_原始结构脱敏输入.xlsx")
d3, H3 = load("基101-2002_原始结构脱敏输入.xlsx")

pow_fields = ["电站锅炉/燃气轮机编号", "电站锅炉/燃气轮机类型", "电站锅炉燃烧方式"]
ind_fields = ["工业锅炉编号", "工业锅炉类型", "工业锅炉燃烧方式"]

def has(col, r):
    v = s(r[H2[col]])
    return v != "" and v != "0.000" and v != "0"

dev_counts = Counter()   # (credit, 'POW'|'IND') -> n
for r in d2:
    cr = s(r[H2["统一社会信用代码"]])
    if any(has(c, r) for c in pow_fields):
        dev_counts[(cr, "POW")] += 1
    if any(has(c, r) for c in ind_fields):
        dev_counts[(cr, "IND")] += 1

fac_counts = Counter()   # (credit, 'POW'|'IND') -> n (GYGL->IND, DZGL->POW)
for r in d3:
    cr = s(r[H3["统一社会信用代码"]])
    code = s(r[H3["对应的排放口代码"]])
    if code == "GYGL":
        fac_counts[(cr, "IND")] += 1
    elif code == "DZGL":
        fac_counts[(cr, "POW")] += 1

keys = set(dev_counts) | set(fac_counts)
match = 0
dev_more = 0
fac_more = 0
examples = []
for k in sorted(keys):
    dv = dev_counts.get(k, 0)
    fv = fac_counts.get(k, 0)
    if dv == fv:
        match += 1
    elif dv > fv:
        dev_more += 1
        if len(examples) < 12:
            examples.append((k, dv, fv, "dev>fac"))
    else:
        fac_more += 1
        if len(examples) < 12:
            examples.append((k, dv, fv, "fac>dev"))
print("credits with device rows:", len(dev_counts))
print("credits with category facilities:", len(fac_counts))
print("equal:", match, "dev>fac:", dev_more, "fac>dev:", fac_more)
for e in examples:
    print("  ", e)

# per credit, list GYGL facilities' processes and efficiencies (sample)
print("\nsample credits with both IND devices and GYGL facilities:")
shown = 0
for (cr, cat), fv in sorted(fac_counts.items()):
    if cat == "IND" and dev_counts.get((cr, "IND"), 0) > 0 and fv >= 1 and shown < 6:
        print("credit", cr, "devices:", dev_counts[(cr, "IND")], "GYGL facilities:", fv)
        for r in d3:
            if s(r[H3["统一社会信用代码"]]) == cr and s(r[H3["对应的排放口代码"]]) == "GYGL":
                print("     ", s(r[H3["处理工艺名称"]]), "eff=", s(r[H3["去除效率（%）"]]))
        shown += 1

# distribution of how many facilities per credit
print("\nfacilities per credit (IND):")
hist = Counter()
for (cr, cat), fv in fac_counts.items():
    if cat == "IND":
        hist[fv] += 1
for k in sorted(hist):
    print("  ", k, hist[k])
