# -*- coding: utf-8 -*-
"""Catalog distinct process names for GYGL/DZGL facilities with eff stats."""
import openpyxl
from collections import Counter, defaultdict

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/050%规模/01_工业锅炉/03_通用工具调用型Agent/R1/inputs"

def load(path):
    wb = openpyxl.load_workbook(BASE + "/" + path, read_only=True, data_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    H = {h: i for i, h in enumerate(rows[0])}
    return rows[1:], H

def s(v):
    return "" if v is None else str(v).strip()

d3, H3 = load("基101-2002_原始结构脱敏输入.xlsx")

for cat in ("GYGL", "DZGL"):
    rows = [r for r in d3 if s(r[H3["对应的排放口代码"]]) == cat]
    print("=== %s: %d rows ===" % (cat, len(rows)))
    stat = Counter()
    eff_stats = defaultdict(lambda: [0, 0])
    for r in rows:
        proc = s(r[H3["处理工艺名称"]])
        eff = s(r[H3["去除效率（%）"]])
        stat[proc] += 1
        if eff:
            eff_stats[proc][0] += 1
        else:
            eff_stats[proc][1] += 1
    for proc, n in stat.most_common():
        f, b = eff_stats[proc]
        print("  %-40s n=%-4d eff_filled=%d eff_blank=%d" % (repr(proc)[:40], n, f, b))
