{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Check fuel2 tce rows, 低氮 flag, empty-credit facilities, coal S/ash fill."""
import openpyxl
from collections import Counter

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/050%规模/01_工业锅炉/03_通用工具调用型Agent/R1/inputs"

def load(path):
    wb = openpyxl.load_workbook(BASE + "/" + path, read_only=True, data_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    H = {h: i for i, h in enumerate(rows[0])}
    return rows[1:], H

def s(v):
    return "" if v is None else str(v).strip()

d2, H2 = load("基102-2002_原始结构脱敏输入.xlsx")

print("-- fuel2 with 吨标准煤 unit --")
for r in d2:
    if s(r[H2["燃料二消耗量单位"]]) == "吨标准煤":
        print("  ", s(r[H2["序号"]]), s(r[H2["燃料二类型"]]), s(r[H2["燃料二消耗量"]]),
              "fuel1:", s(r[H2["燃料一类型"]]), s(r[H2["燃料一消耗量"]]), s(r[H2["燃料一消耗量单位"]]))

print("\n-- 低氮燃烧 flag distribution (IND rows) --")
cnt = Counter()
for r in d2:
    if s(r[H2["工业锅炉编号"]]):
        cnt[s(r[H2["是否采用低氮燃烧技术"]])] += 1
print(cnt)

print("\n-- coal rows: S and ash fill --")
coal_types = ("一般烟煤", "无烟煤", "原煤", "褐煤", "煤制品")
ns = 0
na = 0
both = 0
for r in d2:
    if s(r[H2["燃料一类型"]]) in coal_types:
        has_s = bool(s(r[H2["燃料一平均收到基含硫量"]]))
        has_a = bool(s(r[H2["燃料一平均收到基灰分（%）"]]))
        if has_s and has_a:
            both += 1
        elif has_s:
            ns += 1
        elif has_a:
            na += 1
print("coal fuel1 rows:", sum(1 for r in d2 if s(r[H2["燃料一类型"]]) in coal_types))
print("S+ash:", both, "S only:", ns, "ash only:", na)

# sample coal row values
print("\n-- sample coal rows --")
n = 0
for r in d2:
    if s(r[H2["燃料一类型"]]) == "一般烟煤" and n < 3:
        print("  S:", s(r[H2["燃料一平均收到基含硫量"]]), "ash:", s(r[H2["燃料一平均收到基灰分（%）"]]),
              "bm:", s(r[H2["工业锅炉燃烧方式"]]), "cons:", s(r[H2["燃料一消耗量"]]), s(r[H2["燃料一消耗量单位"]]),
              "LHV:", s(r[H2["燃料一低位发热量（千卡/千克或千卡/标准立方米）"]]))
        n += 1

# empty-credit facilities with GYGL/DZGL
d3, H3 = load("基101-2002_原始结构脱敏输入.xlsx")
cnt3 = Counter()
for r in d3:
    if not s(r[H3["统一社会信用代码"]]):
        cnt3[s(r[H3["对应的排放口代码"]])] += 1
print("\n-- empty-credit facilities by code --", dict(cnt3))

# how many IND sources have zero GYGL facilities (uncontrolled or missing data)
from collections import defaultdict
fac_by_credit = defaultdict(list)
for r in d3:
    fac_by_credit[(s(r[H3["统一社会信用代码"]]), s(r[H3["对应的排放口代码"]]))].append(r)
no_fac = 0
with_fac = 0
for r in d2:
    if s(r[H2["工业锅炉编号"]]):
        key = (s(r[H2["统一社会信用代码"]]), "GYGL")
        if fac_by_credit.get(key):
            with_fac += 1
        else:
            no_fac += 1
print("IND rows with GYGL facilities:", with_fac, "without:", no_fac)
